<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
#define rep(i,a,b) for(int i=(a);i<(b);++i)
#define per(i,a,b) for(int i=(b)-1;i>=(a);--i)
#define ll long long
#define lb(x) ((x)&-(x))
#define pii pair<int,int>
#define vi vector<int>
#define pb push_back
#define fi first
#define se second
#define de(x) cout<<#x<<" x"<<endl
#define LCAFA rep(i,1,20)rep(j,1,n+1)fa[j][i]=fa[fa[j][i-1]][i-1]
#define all(x) x.begin(),x.end()
#define ls(x) x<<1
#define rs(x) x<<1|1
#define pr(x) {for(auto v:x)cout<<v<<' ';cout<<#x<<endl;}
using namespace std;
const int N=500+9;
int mod=998244353;
inline int add(int a,const int &b){
	a+=b;
	if(a>=mod)a-=mod;
	return a;
} 
inline int mul(const int &a,const int &b){
	return 1ll*a*b%mod;
}
int dp[N][N],dp2[N][N],C[N][N],f[N],g[N];
int main(){
	int n,m;
	scanf("%d%d%d",&n,&m,&mod);
	rep(i,0,n+1){
		C[i][0]=1;
		rep(j,0,i)C[i][j+1]=add(C[i-1][j+1],C[i-1][j]);
	}
	f[0]=1,g[0]=0;
	rep(i,1,m+1){
		rep(j,1,i+1){
			f[i]=add(f[i],mul(mul(C[i-1][j-1],i+1),mul(f[j-1],f[i-j])));
			g[i]=add(g[i],mul(mul(C[i-1][j-1],i+1),add(mul(f[j-1],g[i-j]),mul(g[j-1],f[i-j]))));
			g[i]=add(g[i],mul(mul(C[i-1][j-1],(j-1)*j/2+(i-j+1)*(i-j)/2),mul(f[j-1],f[i-j])));
		}
	}
	++n;
	dp[0][0]=1,dp2[0][0]=0;
	rep(i,0,n){
		rep(j,0,m+1){
			for(int k=0;j+k<=m&&i+k+1<=n;++k){
				dp[i+k+1][j+k]=add(dp[i+k+1][j+k],mul(mul(dp[i][j],f[k]),C[j+k][j]));
				dp2[i+k+1][j+k]=add(dp2[i+k+1][j+k],mul(C[j+k][j],add(mul(dp2[i][j],f[k]),mul(dp[i][j],g[k])))); 
			}
		}
	}
	cout<<dp2[n][m];
}

